1	// 首页“创建公开房间”在创建请求连接失败时的界面回归测试。
2	//
3	// 与其他浏览器回归文件的分工：
4	//   - ui.test.mjs：创建成功/被拒（服务返回业务原因）、成功后列表竞态刷新、
5	//     名称整理与长度边界；
6	//   - ui-capacity-linkage.test.mjs / ui-turn-seconds.test.mjs / ui-mixed-records.test.mjs：
7	//     人数联动、时间限制与混合记录展示；
8	//   - 本文件只盯住“创建请求尚未送达服务就连接失败”这一条路径：此时没有服务端
9	//     返回的业务拒绝原因，也没有已确认的新房间编号，页面必须沿用现有的连接失败
10	//     反馈（“无法连接服务，请确认服务仍在运行后重试。”），不能显示成输入错误
11	//     或房间列表读取失败。
12	//
13	// 覆盖的产品行为：
14	//   1. 用户先看到正常加载的已有房间，再填写一份合法的飞行棋配置（4 人、60 秒、
15	//      名称含首尾空格、内部空格与表情）；
16	//   2. 提交进入等待时创建按钮暂时不可用；连接失败后表单区域显示连接失败提示，
17	//      按钮恢复可用；名称保持输入时的原貌，规则、人数、时间全部保留，人数选择
18	//      仍然可用，不退回“未选择规则”的初始状态；
19	//   3. 房间列表保留提交前的内容与排列次序，不出现新房间、成功提示或虚假编号；
20	//      服务端查询到的房间记录没有增加，已有记录及其附带字段保持原值；
21	//   4. 连接恢复后用户不刷新页面、不重新填写，直接再次提交即可正常创建：新房间
22	//      使用保留的飞行棋/4 人/60 秒配置，名称仅去掉首尾空白（内部空格与表情保留），
23	//      成功提示中的非空编号与服务端返回一致，列表在已有记录之后展示新房间且原有
24	//      记录内容与次序不变；连接失败提示被成功结果替换，表单恢复初始填写状态
25	//      （名称/时间为空、规则未选择、人数不可填写），创建按钮仍可使用。
26	//
27	// 失败条件限定为“请求未送达服务”（用请求拦截在请求发出前中止来模拟，并以
28	// 服务端记录数不变佐证请求确实没有到达）；响应途中断开时房间是否已保存不在
29	// 本文件的判断范围内。既有区分继续保留：服务已确认创建成功、仅后续列表刷新
30	// 连接失败时，仍保留成功提示及编号，不按创建连接失败处理（本文件第二个用例
31	// 在连接层面覆盖这一区分，HTTP 层由 ui.test.mjs 覆盖）。
32	//
33	// 运行：npm test（需要系统 Chrome，可用 CHROME_PATH 指定路径）。
34	
35	import { test, before, after } from 'node:test';
36	import assert from 'node:assert/strict';
37	import { execFile, spawn } from 'node:child_process';
38	import { mkdtemp, writeFile, rm } from 'node:fs/promises';
39	import { tmpdir } from 'node:os';
40	import path from 'node:path';
41	import { promisify } from 'node:util';
42	import puppeteer from 'puppeteer-core';
43	
44	const repoRoot = import.meta.dirname;
45	const chromePath = process.env.CHROME_PATH || '/usr/bin/google-chrome';
46	
47	const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
48	
49	let serverBin;
50	let browser;
51	
52	// 与其他界面回归文件相同的种子记录：带附带字段（note/tags/extra），
53	// 用于验证连接失败与恢复后成功创建的整个过程中，原有房间的内容、
54	// 次序与附带字段保持不变。
55	const SEED_ALPHA =
56	  '{"id":"seed-alpha","name":"晨间飞行棋","game":"ludo","capacity":4,"turnSeconds":30,' +
57	  '"status":"playing","visibility":"public","createdAt":"2026-01-01T08:00:00Z","note":"保留我","tags":["老友","周赛"]}';
58	const SEED_BETA =
59	  '{"id":"seed-beta","name":"午夜五子棋","game":"gomoku","capacity":2,"turnSeconds":0,' +
60	  '"status":"waiting","visibility":"public","createdAt":"2026-01-02T23:00:00Z","extra":{"rank":3}}';
61	
62	const SUCCESS_PREFIX = '房间已创建，编号：';
63	const CONN_FAILURE_TEXT = '无法连接服务，请确认服务仍在运行后重试。';
64	const LIST_ERROR_TEXT = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
65	
66	// 创建成功后的表单复位状态：名称/规则/时间清空，人数恢复“未选择规则”时的
67	// 禁用占位状态，创建按钮恢复可用。
68	const RESET_FORM = {
69	  name: '',
70	  game: '',
71	  capacity: '',
72	  capacityDisabled: true,
73	  turnSeconds: '',
74	  submitDisabled: false,
75	};
76	
77	before(async () => {
78	  const dir = await mkdtemp(path.join(tmpdir(), 'score-arena-uibin-'));
79	  serverBin = path.join(dir, 'score-arena');
80	  await promisify(execFile)('go', ['build', '-o', serverBin, '.'], { cwd: repoRoot });
81	  browser = await puppeteer.launch({
82	    executablePath: chromePath,
83	    headless: true,
84	    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
85	  });
86	});
87	
88	after(async () => {
89	  if (browser) await browser.close();
90	  if (serverBin) await rm(path.dirname(serverBin), { recursive: true, force: true });
91	});
92	
93	// startServer 在 dataDir 上启动真实服务子进程（--port 0 自动选端口），返回基地址。
94	function startServer(t, dataDir) {
95	  const proc = spawn(
96	    serverBin,
97	    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
98	    { stdio: ['ignore', 'pipe', 'inherit'] },
99	  );
100	  t.after(() => { proc.kill('SIGKILL'); });
101	  return new Promise((resolve, reject) => {
102	    let buf = '';
103	    const timer = setTimeout(() => reject(new Error('等待服务监听地址超时')), 15000);
104	    proc.stdout.on('data', (chunk) => {
105	      buf += chunk.toString();
106	      const m = buf.match(/listening on (http:\/\/\S+)/);
107	      if (m) {
108	        clearTimeout(timer);
109	        resolve(m[1]);
110	      }
111	    });
112	    proc.on('exit', (code) => {
113	      clearTimeout(timer);
114	      reject(new Error(`服务在输出监听地址前退出，退出码 ${code}`));
115	    });
116	  });
117	}
118	
119	async function seedRooms(dataDir, ...records) {
120	  await writeFile(path.join(dataDir, 'rooms.json'), '[\n' + records.join(',\n') + '\n]\n');
121	}
122	
123	// 每个用例使用独立的数据目录、服务进程与页面，互不影响；打开页面时已有两条
124	// 种子房间正常加载，用于比对连接失败前后的列表内容与次序。
125	async function setupPage(t) {
126	  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-uidata-'));
127	  t.after(() => rm(dataDir, { recursive: true, force: true }));
128	  await seedRooms(dataDir, SEED_ALPHA, SEED_BETA);
129	  const baseURL = await startServer(t, dataDir);
130	  const page = await browser.newPage();
131	  t.after(() => page.close());
132	  await page.goto(baseURL, { waitUntil: 'load' });
133	  await waitForRowCount(page, 2);
134	  return { page, baseURL };
135	}
136	
137	function waitForRowCount(page, n) {
138	  return page.waitForFunction(
139	    (want) => document.querySelectorAll('#list-area table tbody tr').length === want,
140	    { timeout: 10000 },
141	    n,
142	  );
143	}
144	
145	function waitForMessageKind(page, kind) {
146	  return page.waitForFunction(
147	    (cls) => document.getElementById('form-msg').classList.contains(cls),
148	    { timeout: 10000 },
149	    kind,
150	  );
151	}
152	
153	// readRows 读取列表每一行的单元格文本、创建时间单元格的 title（原始 ISO 时间）
154	// 以及状态列徽标文本，用于逐格比对内容与次序。
155	function readRows(page) {
156	  return page.$$eval('#list-area table tbody tr', (trs) =>
157	    trs.map((tr) => {
158	      const tds = [...tr.querySelectorAll('td')];
159	      return {
160	        cells: tds.map((td) => td.textContent),
161	        timeTitle: tds[6] ? tds[6].getAttribute('title') : null,
162	        badge: tds[5] && tds[5].querySelector('.badge')
163	          ? tds[5].querySelector('.badge').textContent
164	          : null,
165	      };
166	    }),
167	  );
168	}
169	
170	function readFormState(page) {
171	  return page.evaluate(() => ({
172	    name: document.getElementById('name').value,
173	    game: document.getElementById('game').value,
174	    capacity: document.getElementById('capacity').value,
175	    capacityDisabled: document.getElementById('capacity').disabled,
176	    turnSeconds: document.getElementById('turnSeconds').value,
177	    submitDisabled: document.getElementById('submit').disabled,
178	  }));
179	}
180	
181	function readMessage(page) {
182	  return page.evaluate(() => {
183	    const el = document.getElementById('form-msg');
184	    return { className: el.className, text: el.textContent };
185	  });
186	}
187	
188	function readListArea(page) {
189	  return page.evaluate(() => ({
190	    text: document.getElementById('list-area').textContent,
191	    hasTable: !!document.querySelector('#list-area table'),
192	    errorText: document.querySelector('#list-area .list-error')
193	      ? document.querySelector('#list-area .list-error').textContent
194	      : null,
195	    emptyText: document.querySelector('#list-area .empty')
196	      ? document.querySelector('#list-area .empty').textContent
197	      : null,
198	  }));
199	}
200	
201	// nextCreated 在下一次创建响应到达时解析出创建结果（服务端保存后的房间）。
202	function nextCreated(page) {
203	  return new Promise((resolve, reject) => {
204	    page.on('response', (resp) => {
205	      if (resp.request().method() === 'POST' && resp.url().endsWith('/api/rooms')) {
206	        resp.json().then(resolve, reject);
207	      }
208	    });
209	  });
210	}
211	
212	// readServerRooms 直接读接口，确认服务端实际保存的记录（绕过页面展示）。
213	async function readServerRooms(baseURL) {
214	  const res = await fetch(baseURL + '/api/rooms');
215	  assert.equal(res.status, 200);
216	  return (await res.json()).rooms;
217	}
218	
219	// 断言两条种子房间渲染正确（内容、次序、附带字段不影响展示）。
220	function assertSeedRows(rows) {
221	  assert.deepEqual(
222	    rows.map((r) => r.cells.slice(0, 6)),
223	    [
224	      ['seed-alpha', '晨间飞行棋', '飞行棋', '4 人', '30 秒', 'playing'],
225	      ['seed-beta', '午夜五子棋', '五子棋', '2 人', '不限时', '未开始'],
226	    ],
227	    '种子房间的展示内容或次序不符合预期',
228	  );
229	  assert.equal(rows[0].timeTitle, '2026-01-01T08:00:00Z');
230	  assert.equal(rows[1].timeTitle, '2026-01-02T23:00:00Z');
231	  assert.equal(rows[1].badge, '未开始');
232	}
233	
234	// 填写合法的飞行棋表单：4 人、60 秒，名称含首尾空格、内部空格与表情。
235	const RAW_NAME = '  周末 飞行棋 🎲 友谊赛  ';
236	const TRIMMED_NAME = '周末 飞行棋 🎲 友谊赛';
237	
238	async function fillLudoForm(page) {
239	  await page.type('#name', RAW_NAME);
240	  await page.select('#game', 'ludo');
241	  await page.waitForFunction(
242	    () => !document.getElementById('capacity').disabled,
243	    { timeout: 5000 },
244	  );
245	  await page.select('#capacity', '4');
246	  await page.type('#turnSeconds', '60');
247	}
248	
249	// 主用例：创建请求尚未送达服务就连接失败 → 保留填写内容 → 连接恢复后直接
250	// 再次提交成功。覆盖从等待、连接失败到恢复后成功提交的实际页面变化，
251	// 不能只确认错误文案出现。
252	test('创建请求未送达服务的连接失败：保留填写内容，恢复后不刷新页面直接重提交成功', { timeout: 60000 }, async (t) => {
253	  const { page, baseURL } = await setupPage(t);
254	
255	  // 用户先看到正常加载的已有房间。
256	  const initialRows = await readRows(page);
257	  assertSeedRows(initialRows);
258	  const seedRooms = await readServerRooms(baseURL);
259	  assert.equal(seedRooms.length, 2);
260	
261	  // 记录页面尝试发出的每一次创建请求体（含将被中止的第一次），
262	  // 用于区分“页面尝试发送”与“请求真正送达服务”。
263	  const postBodies = [];
264	  // 第一次创建请求在送达服务前被中止（模拟连接失败），其余请求照常放行。
265	  let failFirstPost = true;
266	  let abortFirstPost;
267	  const firstPostInFlight = new Promise((resolve) => { abortFirstPost = resolve; });
268	  await page.setRequestInterception(true);
269	  page.on('request', (req) => {
270	    if (req.method() === 'POST' && req.url().endsWith('/api/rooms')) {
271	      postBodies.push(req.postData());
272	      if (failFirstPost) {
273	        failFirstPost = false;
274	        // 挂起请求以观察等待状态，测试手动中止；中止发生在请求发出前，
275	        // 服务端不会收到这次创建。
276	        firstPostInFlight.then(() => req.abort());
277	        return;
278	      }
279	    }
280	    req.continue();
281	  });
282	
283	  // 填写一份合法的飞行棋配置：4 人、60 秒，名称含首尾空格、内部空格与表情。
284	  await fillLudoForm(page);
285	  await page.click('#submit');
286	
287	  // 提交进入等待：创建按钮暂时不可用，且不是瞬间恢复。
288	  await page.waitForFunction(
289	    () => document.getElementById('submit').disabled,
290	    { timeout: 5000 },
291	  );
292	  await sleep(300);
293	  assert.equal(
294	    (await readFormState(page)).submitDisabled,
295	    true,
296	    '提交等待期间创建按钮应保持不可用',
297	  );
298	
299	  // 请求尚未送达服务就连接失败。
300	  abortFirstPost();
301	
302	  // 表单区域显示现有的连接失败反馈：不是输入错误，也不是列表读取失败。
303	  await waitForMessageKind(page, 'error');
304	  const msg = await readMessage(page);
305	  assert.equal(msg.text, CONN_FAILURE_TEXT, '应显示现有的连接失败提示');
306	  assert.ok(msg.className.includes('error'), '连接失败提示应以错误样式显示在表单区域');
307	  assert.ok(!msg.className.includes('ok'), '连接失败时不应显示成功提示');
308	  assert.ok(!msg.text.includes(SUCCESS_PREFIX), '连接失败时不应出现成功编号');
309	  assert.ok(!msg.text.includes('已创建'), '连接失败时不应出现成功文案');
310	
311	  // 名称保持输入时的原貌，规则、人数、时间全部保留，人数选择仍然可用，
312	  // 不因失败恢复成未选择规则的初始状态；按钮恢复可用。
313	  assert.deepEqual(await readFormState(page), {
314	    name: RAW_NAME,
315	    game: 'ludo',
316	    capacity: '4',
317	    capacityDisabled: false,
318	    turnSeconds: '60',
319	    submitDisabled: false,
320	  }, '连接失败后应保留全部已填内容并恢复按钮可用');
321	
322	  // 房间列表保留提交前的内容和排列次序：不出现新房间，也不被换成加载失败。
323	  assert.deepEqual(await readRows(page), initialRows, '连接失败时不应改动房间列表');
324	  let list = await readListArea(page);
325	  assert.ok(list.hasTable, '连接失败时已有房间列表应保留');
326	  assert.equal(list.errorText, null, '创建连接失败不应显示成房间列表读取失败');
327	  assert.ok(!list.text.includes('加载失败'), '列表区域不应出现加载失败文案');
328	
329	  // 服务端查询到的房间记录没有增加，已有记录及其附带字段保持原值
330	  // （同时佐证第一次创建请求确实没有送达服务）。
331	  assert.deepEqual(
332	    await readServerRooms(baseURL),
333	    seedRooms,
334	    '连接失败后服务端记录不应增加，已有记录及附带字段保持原值',
335	  );
336	
337	  // 连接恢复：用户不刷新页面、不重新填写，直接再次提交。
338	  const createdPromise = nextCreated(page);
339	  await page.click('#submit');
340	
341	  await waitForMessageKind(page, 'ok');
342	  const created = await createdPromise;
343	
344	  // 重试只使用保留的配置发出请求，名称仍是输入时的原貌（页面侧不裁剪）。
345	  assert.equal(postBodies.length, 2, '应先后尝试两次创建请求');
346	  assert.deepEqual(JSON.parse(postBodies[1]), {
347	    name: RAW_NAME,
348	    game: 'ludo',
349	    capacity: 4,
350	    turnSeconds: 60,
351	  }, '重试请求应沿用保留的填写内容');
352	
353	  // 新房间使用保留的飞行棋、4 人、60 秒配置；名称仅去掉首尾空白，
354	  // 内部空格与表情保留。
355	  assert.ok(created.id, '创建结果应包含非空的新房间编号');
356	  assert.equal(created.name, TRIMMED_NAME, '名称应仅去掉首尾空白，保留内部空格与表情');
357	  assert.equal(created.game, 'ludo');
358	  assert.equal(created.capacity, 4);
359	  assert.equal(created.turnSeconds, 60);
360	  assert.equal(created.status, 'waiting');
361	  assert.equal(created.visibility, 'public');
362	
363	  // 连接失败提示被成功结果替换，成功提示中的编号与服务端返回的新房间一致。
364	  const msg2 = await readMessage(page);
365	  assert.ok(msg2.className.includes('ok'), '连接失败提示应被成功结果替换');
366	  assert.ok(msg2.text.startsWith(SUCCESS_PREFIX), `应显示成功提示，实际: ${msg2.text}`);
367	  assert.ok(!msg2.text.includes(CONN_FAILURE_TEXT), '成功结果不应残留连接失败提示');
368	  assert.equal(
369	    msg2.text.slice(SUCCESS_PREFIX.length),
370	    created.id,
371	    '成功提示中的编号应与服务端返回的新房间一致',
372	  );
373	
374	  // 表单恢复初始填写状态：名称和时间为空，规则未选择，人数不可填写。
375	  assert.deepEqual(await readFormState(page), RESET_FORM, '成功后表单应恢复初始填写状态');
376	
377	  // 列表刷新后在已有记录之后展示新房间，原有记录的内容和次序不变。
378	  await waitForRowCount(page, 3);
379	  const rows = await readRows(page);
380	  assert.deepEqual(rows.slice(0, 2), initialRows, '原有房间的内容或次序被改变');
381	  const added = rows[2];
382	  assert.equal(added.cells[0], created.id, '新行编号应与创建结果一致');
383	  assert.equal(added.cells[1], TRIMMED_NAME, '新行名称应仅去掉首尾空白并保留内部空格与表情');
384	  assert.equal(added.cells[1], created.name, '新行名称应与创建结果一致');
385	  assert.equal(added.cells[2], '飞行棋');
386	  assert.equal(added.cells[3], '4 人');
387	  assert.equal(added.cells[4], '60 秒');
388	  assert.equal(added.cells[5], '未开始');
389	  assert.equal(added.badge, '未开始', '状态应以徽标显示“未开始”');
390	  assert.equal(added.timeTitle, created.createdAt, '新行创建时间应与创建结果一致');
391	
392	  // 服务端仅在原有记录之后追加这一条，已有记录及附带字段保持原值。
393	  const serverRooms = await readServerRooms(baseURL);
394	  assert.equal(serverRooms.length, 3, '服务端应只新增这一条房间');
395	  assert.deepEqual(serverRooms.slice(0, 2), seedRooms, '已有记录及附带字段应保持原值');
396	  assert.equal(serverRooms[2].id, created.id);
397	  assert.equal(serverRooms[2].name, TRIMMED_NAME);
398	  assert.equal(serverRooms[2].game, 'ludo');
399	  assert.equal(serverRooms[2].capacity, 4);
400	  assert.equal(serverRooms[2].turnSeconds, 60);
401	
402	  // 请求完成后创建按钮仍可使用。
403	  assert.equal(
404	    (await readFormState(page)).submitDisabled,
405	    false,
406	    '请求完成后创建按钮应恢复可用',
407	  );
408	});
409	
410	// 既有区分在连接层面的保留：服务已确认创建成功、仅后续列表刷新连接失败时，
411	// 仍保留成功提示及编号，不按创建连接失败处理；列表区域显示加载失败。
412	test('创建成功但列表刷新连接失败：保留成功提示与编号，不按创建连接失败处理', { timeout: 60000 }, async (t) => {
413	  const { page, baseURL } = await setupPage(t);
414	  const initialRows = await readRows(page);
415	  assertSeedRows(initialRows);
416	
417	  // 页面正常加载后，仅让后续的列表读取连接失败（请求在送达前被中止）；
418	  // 创建请求照常放行到真实服务。
419	  await page.setRequestInterception(true);
420	  page.on('request', (req) => {
421	    if (req.method() === 'GET' && req.url().endsWith('/api/rooms')) {
422	      req.abort();
423	    } else {
424	      req.continue();
425	    }
426	  });
427	
428	  const createdPromise = nextCreated(page);
429	  await page.type('#name', '刷新连接失败的房间');
430	  await page.select('#game', 'gomoku');
431	  await page.waitForFunction(
432	    () => !document.getElementById('capacity').disabled &&
433	      document.getElementById('capacity').value === '2',
434	    { timeout: 5000 },
435	  );
436	  await page.type('#turnSeconds', '0');
437	  await page.click('#submit');
438	
439	  // 创建已被服务确认成功：成功提示与非空编号保留，不显示连接失败文案。
440	  await waitForMessageKind(page, 'ok');
441	  const created = await createdPromise;
442	  assert.ok(created.id, '创建结果应包含新房间编号');
443	  const msg = await readMessage(page);
444	  assert.ok(msg.text.startsWith(SUCCESS_PREFIX), `应保留创建成功提示，实际: ${msg.text}`);
445	  assert.equal(msg.text.slice(SUCCESS_PREFIX.length), created.id, '提示编号应与创建结果一致');
446	  assert.ok(!msg.text.includes(CONN_FAILURE_TEXT), '已确认成功的创建不应显示连接失败提示');
447	
448	  // 表单仍按成功处理（恢复初始填写状态）。
449	  assert.deepEqual(await readFormState(page), RESET_FORM, '列表刷新连接失败不应影响已成功创建的表单处理');
450	
451	  // 列表区域明确显示加载失败，而不是空列表提示或旧内容。
452	  await page.waitForFunction(
453	    () => !!document.querySelector('#list-area .list-error'),
454	    { timeout: 10000 },
455	  );
456	  const list = await readListArea(page);
457	  assert.equal(list.errorText, LIST_ERROR_TEXT);
458	  assert.equal(list.emptyText, null, '列表刷新连接失败时不得显示“还没有房间记录”');
459	  assert.ok(!list.hasTable, '列表刷新连接失败时不应展示旧表格冒充最新列表');
460	
461	  // 列表读取连接失败落定后，成功提示与编号仍然保留，未被改写成创建失败。
462	  const msgAfter = await readMessage(page);
463	  assert.ok(msgAfter.className.includes('ok'), '列表刷新连接失败不应把已完成的创建说成失败');
464	  assert.equal(msgAfter.text, msg.text, '成功提示与编号应保留');
465	  assert.equal((await readFormState(page)).submitDisabled, false, '本次操作完成后创建按钮应恢复可用');
466	
467	  // 服务端确实已保存本次创建（证明创建本身成功，只是刷新连接失败）。
468	  const serverRooms = await readServerRooms(baseURL);
469	  assert.equal(serverRooms.length, 3, '服务端应已保存新房间');
470	  assert.equal(serverRooms[2].id, created.id, '服务端保存的编号应与页面提示一致');
471	});
