async function installGate(page, { continueRest = false, holdRefresh = false } = {}) {
  const postBodies = [];
  let heldPost = null;
  const postWaiters = [];
  let heldRefresh = null;
  const refreshWaiters = [];

  await page.setRequestInterception(true);
  page.on('request', (req) => {
    const isPost = req.method() === 'POST' && req.url().endsWith('/api/rooms');
    const isRoomsGet = req.method() === 'GET' && req.url().endsWith('/api/rooms');
    if (isPost) {
      postBodies.push(req.postData());
      // 第一个 POST 挂起；配置了 continueRest 时，再次提交直接放行。
      if (postBodies.length > 1 && continueRest) {
        req.continue();
        return;
      }
      heldPost = req;
      postWaiters.forEach((fn) => fn(req));
      return;
    }
    if (isRoomsGet && holdRefresh) {
      heldRefresh = req;
      refreshWaiters.forEach((fn) => fn(req));
      return;
    }
    req.continue();
  });

  return {
    postBodies,
    waitPostHeld: () => new Promise((resolve) => postWaiters.push(resolve)),
    waitRefreshHeld: () => new Promise((resolve) => refreshWaiters.push(resolve)),
    async releasePost() {
      const req = heldPost;
      heldPost = null;
      await req.continue();
    },
    async rejectPost(status, body) {
      const req = heldPost;
      heldPost = null;
      await req.respond({
        status,
        contentType: 'application/json; charset=utf-8',
        body: JSON.stringify(body),
      });
    },
    async releaseRefresh() {
      const req = heldRefresh;
      heldRefresh = null;
      await req.continue();
    },
  };
}

toolUseResult.newString:
async function installGate(page, { continueRest = false, holdRefresh = false } = {}) {
  const postBodies = [];
  let heldPost = null;
  let heldRefresh = null;
  let refreshCount = 0;

  // 轮询等待，避免“事件在注册 waiter 之前就已触发”的竞态（点击 await 返回时
  // 请求可能已经挂起）。与 ui.test.mjs 的 gate.waitFor 同一做法。
  async function waitUntil(predicate, message) {
    const deadline = Date.now() + 10000;
    while (!predicate()) {
      if (Date.now() > deadline) throw new Error(message);
      await sleep(15);
    }
  }

  await page.setRequestInterception(true);
  page.on('request', (req) => {
    const isPost = req.method() === 'POST' && req.url().endsWith('/api/rooms');
    const isRoomsGet = req.method() === 'GET' && req.url().endsWith('/api/rooms');
    if (isPost) {
      postBodies.push(req.postData());
      // 第一个 POST 挂起；配置了 continueRest 时，再次提交直接放行。
      if (postBodies.length > 1 && continueRest) {
        req.continue();
        return;
      }
      heldPost = req;
      return;
    }
    if (isRoomsGet && holdRefresh) {
      heldRefresh = req;
      refreshCount += 1;
      return;
    }
    req.continue();
  });

  return {
    postBodies,
    // 等待第一次创建请求真正发出并处于挂起状态。
    waitPostHeld: () =>
      waitUntil(() => heldPost !== null, '等待挂起的创建请求超时'),
    waitRefreshHeld: () =>
      waitUntil(() => refreshCount >= 1 && heldRefresh !== null, '等待挂起的列表刷新超时'),
    async releasePost() {
      const req = heldPost;
      heldPost = null;
      await req.continue();
    },
    async rejectPost(status, body) {
      const req = heldPost;
      heldPost = null;
      await req.respond({
        status,
        contentType: 'application/json; charset=utf-8',
        body: JSON.stringify(body),
      });
    },
    async releaseRefresh() {
      const req = heldRefresh;
      heldRefresh = null;
      await req.continue();
    },
  };
}

